import React from 'react';

export default function PlanDisplay({ plan, currentStep, onComplete }) {
  if (!plan || plan.length === 0) return null;

  return (
    <div className="bg-slate-800 border border-slate-700 rounded-lg p-4 mb-4">
      <h3 className="text-lg font-semibold text-primary mb-3 flex items-center gap-2">
        <span>📋</span>
        Execution Plan
      </h3>
      <div className="space-y-2">
        {plan.map((subtask) => {
          const isCurrent = currentStep === subtask.id;
          const isCompleted = currentStep > subtask.id;

          return (
            <div
              key={subtask.id}
              className={`p-3 rounded-lg border transition-all ${
                isCompleted
                  ? 'border-success/50 bg-success/5'
                  : isCurrent
                  ? 'border-primary/50 bg-primary/5 animate-pulse'
                  : 'border-slate-700 bg-slate-900/30'
              }`}
            >
              <div className="flex items-start gap-3">
                <span
                  className={`flex-shrink-0 w-6 h-6 rounded-full flex items-center justify-center text-xs font-bold ${
                    isCompleted
                      ? 'bg-success text-white'
                      : isCurrent
                      ? 'bg-primary text-white'
                      : 'bg-slate-700 text-slate-400'
                  }`}
                >
                  {isCompleted ? '✓' : subtask.id}
                </span>
                <div className="flex-1">
                  <p className="font-medium text-slate-200">{subtask.description}</p>
                  {subtask.reasoning && (
                    <p className="text-xs text-slate-500 mt-1 italic">
                      {subtask.reasoning}
                    </p>
                  )}
                  {subtask.tool && (
                    <span className="inline-block mt-1 text-xs px-2 py-1 bg-slate-700 rounded text-slate-300">
                      Tool: {subtask.tool}
                    </span>
                  )}
                </div>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}
